mapper.select:
select  from nad_application_payment
where application_id = #{applicationId} and kind = #{kind}
order by id desc limit 1

mapper.update:
update nad_application_payment
set status = 'PROOF_SUBMITTED', student_txn_no = #{txnNo}, proof_media_id = #{proofMediaId},
    submitted_at = #{now}, version = version + 1, update_by = #{by}, update_time = #{now}
where id = #{id} and status = 'PENDING' and version = #{version} and expires_at > #{now}

update nad_application_payment
set expires_at = #{expiresAt}, version = version + 1, update_by = #{by}, update_time = #{now}
where id = #{id} and status = 'PENDING' and expires_at < #{expiresAt}

update nad_application_payment
set status = 'CONFIRMED', verified_by = #{verifiedBy}, verified_at = #{now}, rejection_reason = null,
    version = version + 1, update_by = #{verifiedBy}, update_time = #{now}
where id = #{id} and status = 'PROOF_SUBMITTED' and version = #{version}

update nad_application_payment
set status = 'REJECTED', verified_by = #{verifiedBy}, verified_at = #{now}, rejection_reason = #{reason},
    version = version + 1, update_by = #{verifiedBy}, update_time = #{now}
where id = #{id} and status = 'PROOF_SUBMITTED' and version = #{version}

update nad_application_payment
set status = 'CANCELLED', version = version + 1, update_by = #{by}, update_time = #{now}
where id = #{id} and status = 'PENDING' and version = #{version}

update nad_application_payment
set status = 'EXPIRED', version = version + 1, update_by = 'system', update_time = #{now}
where id = #{id} and status = 'PENDING' and expires_at <= #{now}
